  Delay11_PS_3_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        Delay11_PS_3_out1 <= '0';
      ELSIF enb = '1' THEN
        Delay11_PS_3_out1 <= Bit_Reduce1_out1;
      END IF;
    END IF;
  END PROCESS Delay11_PS_3_process;


  Bit_Reduce_out1 <= (Delay4_PS_1_out1(10) OR Delay4_PS_1_out1(9) OR Delay4_PS_1_out1(8) OR Delay4_PS_1_out1(7) OR Delay4_PS_1_out1(6) OR Delay4_PS_1_out1(5) OR Delay4_PS_1_out1(4) OR Delay4_PS_1_out1(3) OR Delay4_PS_1_out1(2) OR Delay4_PS_1_out1(1) OR Delay4_PS_1_out1(0));

