  Data_Type_Conversion1_out1 <= signed(Bit_Concat2_out1);

  nfp_in3_signed <= signed(nfp_in3);

  Delay5_PS_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
